let contentUndoHint=null;
function stopContentPlayback(){stopAudio();playing=false;ended=false;stageRenderer.reset();subtitleDragMode=false;if(typeof portraitDragMode!=='undefined')portraitDragMode=false}
function rememberContentUndo(previousScene,previousBlock){contentUndoHint={snapshot:history.at(-1),sceneId:previousScene,selected:previousBlock}}
function deleteStoryBlock(id){const s=scene(),index=s.blocks.findIndex(b=>b.id===id);if(index<0)return;const deleted=s.blocks[index],previousSelected=selected;change(()=>{stopContentPlayback();s.blocks.splice(index,1);if(selected===id||!s.blocks.some(b=>b.id===selected))selected=s.blocks[Math.min(index,s.blocks.length-1)]?.id});rememberContentUndo(s.id,previousSelected);notify(`已删除${types[deleted.type]}，可点击「撤销」恢复`)}
function clearChapter(id){const target=project.scenes.find(s=>s.id===id);if(!target)return;if(!target.blocks.length){notify('本章已经是空白章节');return}const before=sceneId,previousSelected=selected;dialog('清空本章内容',`<p>清空「${esc(target.name)}」中的全部 ${target.blocks.length} 个剧情块，包括对白、旁白、背景、音乐、立绘及分支。<br>保留章节名称、章节设置，以及工程中的角色和素材。可撤销恢复。</p>`,'清空本章',()=>{change(()=>{stopContentPlayback();target.blocks=[];sceneId=id;selected=null;view='script';mode='visual'});rememberContentUndo(before,previousSelected);notify('本章内容已清空，可点击「撤销」恢复')})}
function requestChapterDelete(id){const target=project.scenes.find(s=>s.id===id);if(!target)return;if(project.scenes.length===1){notify('工程至少保留一章，可用「清空」移除本章内容');return}const links=project.scenes.filter(s=>s.id!==id).reduce((n,s)=>n+s.blocks.reduce((count,b)=>count+(b.target===id?1:0)+(b.options||[]).filter(o=>o.target===id).length,0),0);const before=sceneId,previousSelected=selected;dialog('删除章节',`<p>删除「${esc(target.name)}」及其全部 ${target.blocks.length} 个剧情块。${links?`<br>其他章节有 ${links} 处跳转指向这里，删除后将改为结束故事。`:''}<br>可点击「撤销」恢复章节及跳转。</p>`,'删除章节',()=>{change(()=>{stopContentPlayback();const index=project.scenes.findIndex(s=>s.id===id);project.scenes.splice(index,1);for(const s of project.scenes)for(const b of s.blocks){if(b.target===id)b.target='';for(const option of b.options||[])if(option.target===id)option.target=''}if(sceneId===id){sceneId=project.scenes[Math.min(index,project.scenes.length-1)].id;selected=scene().blocks[0]?.id}if(view==='script')mode='visual'});rememberContentUndo(before,previousSelected);notify('章节已删除，可点击「撤销」恢复')})}
function undoContentChange(){if(!history.length){notify('没有可撤销的修改');return}const previous=history.pop(),hint=contentUndoHint?.snapshot===previous?contentUndoHint:null;stopContentPlayback();project=restoreSnapshot(previous);if(hint&&project.scenes.some(s=>s.id===hint.sceneId)){sceneId=hint.sceneId;selected=hint.selected}if(!project.scenes.some(s=>s.id===sceneId))sceneId=project.scenes[0].id;if(!scene().blocks.some(b=>b.id===selected))selected=scene().blocks[0]?.id;contentUndoHint=null;save();draw();notify('已撤销修改')}
const contentActionsDraw=draw;
draw=function(){contentActionsDraw();if(view==='script'){const head=$('.script-panel > .panel-head');head?.insertAdjacentHTML('beforeend',`<div class="chapter-header-actions"><button class="btn small" data-action="undo-content" ${history.length?'':'disabled'}>${ic('undo')} 撤销</button><button class="btn small chapter-danger" data-action="clear-chapter" data-id="${esc(sceneId)}">清空本章</button></div>`)} };
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(!['quick-delete-block','delete-block','clear-chapter','quick-delete-chapter','delete-scene','undo-content'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();if(action==='quick-delete-block'||action==='delete-block')deleteStoryBlock(button.dataset.id||selected);if(action==='clear-chapter')clearChapter(button.dataset.id||sceneId);if(action==='quick-delete-chapter'||action==='delete-scene')requestChapterDelete(button.dataset.id||sceneId);if(action==='undo-content')undoContentChange()},true);
document.addEventListener('keydown',e=>{if(playing||$('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable||view!=='script')return;if(e.key==='Delete'&&selected){e.preventDefault();e.stopImmediatePropagation();deleteStoryBlock(selected)}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.stopImmediatePropagation();undoContentChange()}},true);
draw();
